describe('Video Player Responsive Tablet Viewport', () => {
  beforeEach(() => {
    cy.visit('/video-player');
  });

  it('should resize video player proportionally on tablet viewports', () => {
    // Setup: Open video player on desktop viewport
    cy.viewport('1920x1080');
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="play-button"]').click();

    // Verify initial desktop size
    cy.get('[data-testid="video-player"]').should('have.css', 'width', '1920px');
    cy.get('[data-testid="video-player"]').should('have.css', 'height', '1080px');

    // Navigate to tablet viewport
    cy.viewport('768x1024');

    // Verify video player resizes proportionally
    cy.get('[data-testid="video-player"]').should('have.css', 'width', '768px');
    cy.get('[data-testid="video-player"]').should('have.css', 'height', '1024px');

    // Verify aspect ratio is maintained
    cy.get('[data-testid="video-player"]').should('have.css', 'aspect-ratio', '16/9');

    // Verify controls are still accessible and visible
    cy.get('[data-testid="play-button"]').should('be.visible');
    cy.get('[data-testid="play-button"]').click();

    // Verify video is playing
    cy.get('[data-testid="video-player"]').should('have.class', 'playing');

    // Verify controls are responsive
    cy.get('[data-testid="volume-control"]').should('be.visible');
    cy.get('[data-testid="volume-control"]').click();

    // Verify video player returns to original size when navigating back
    cy.viewport('1920x1080');
    cy.get('[data-testid="video-player"]').should('have.css', 'width', '1920px');
    cy.get('[data-testid="video-player"]').should('have.css', 'height', '1080px');
  });

  it('should handle edge case: video player resizing on very small tablet viewports', () => {
    // Setup: Open video player on desktop viewport
    cy.viewport('1920x1080');
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="play-button"]').click();

    // Navigate to very small tablet viewport
    cy.viewport('320x480');

    // Verify video player resizes to fit the viewport
    cy.get('[data-testid="video-player"]').should('have.css', 'width', '320px');
    cy.get('[data-testid="video-player"]').should('have.css', 'height', '480px');

    // Verify aspect ratio is maintained
    cy.get('[data-testid="video-player"]').should('have.css', 'aspect-ratio', '16/9');

    // Verify video is still playable
    cy.get('[data-testid="video-player"]').should('have.class', 'playing');

    // Verify controls are still accessible and visible
    cy.get('[data-testid="play-button"]').should('be.visible');
    cy.get('[data-testid="play-button"]').click();

    // Verify video player does not overflow the viewport
    cy.get('[data-testid="video-player"]').should('not.be.visible');

    // Verify error message is displayed if video cannot fit
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Video cannot fit in this viewport');

    // Verify user can choose to view full-screen
    cy.get('[data-testid="full-screen-button"]').should('be.visible');
    cy.get('[data-testid="full-screen-button"]').click();

    // Verify video player returns to original size when navigating back
    cy.viewport('1920x1080');
    cy.get('[data-testid="video-player"]').should('have.css', 'width', '1920px');
    cy.get('[data-testid="video-player"]').should('have.css', 'height', '1080px');
  });
});
